create temp table o8_result(proposal jsonb,charge_id uuid); grant select,insert on o8_result to authenticated;
insert into o8_result(proposal) select to_jsonb(p) from public.treatment_plans p where id='fa800000-0000-0000-0000-000000000001';
set local role authenticated; select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claim.sub','fa100000-0000-0000-0000-000000000001',true);
select public.transition_treatment_plan_item_execution('fa300000-0000-0000-0000-000000000001','fa900000-0000-0000-0000-000000000001',1,'ACCEPTED',null,'o8-accept');
select public.transition_treatment_plan_item_execution('fa300000-0000-0000-0000-000000000001','fa900000-0000-0000-0000-000000000001',2,'IN_PROGRESS',null,'o8-start');
select extensions.is((public.get_treatment_plan_completion_context('fa300000-0000-0000-0000-000000000001','fa800000-0000-0000-0000-000000000001')->'cases'->0->>'caseId'),'faa00000-0000-0000-0000-000000000001','completion context exposes only the authoritative open in-progress case');
