insert into o8_result(charge_id) select charge_id from public.complete_treatment_case('fa300000-0000-0000-0000-000000000001','faa00000-0000-0000-0000-000000000001','fa900000-0000-0000-0000-000000000001',1,array['fab00000-0000-0000-0000-000000000001'::uuid],125000,'{"kind":"BRIDGE","units":[{"tooth_fdi":"24","ordinal":1,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"},{"tooth_fdi":"25","ordinal":2,"role":"PONTIC","support_kind":"NONE"},{"tooth_fdi":"26","ordinal":3,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"}]}'::jsonb,'o8-complete-once');
reset role;
select extensions.is((select count(*)::integer from public.procedure_case_finding_resolutions where procedure_case_id='faa00000-0000-0000-0000-000000000001'),1,'only the selected finding is resolved');
select extensions.is((select source_plan_design_id from public.dental_bridges where charge_id=(select charge_id from o8_result where charge_id is not null)),'fa910000-0000-0000-0000-000000000001'::uuid,'current bridge retains its frozen plan-design provenance');
select extensions.is((select count(*)::integer from public.procedure_case_finding_resolutions where finding_entry_id='fab00000-0000-0000-0000-000000000002'),0,'unselected findings remain unresolved');
select extensions.is((select to_jsonb(p) from public.treatment_plans p where id='fa800000-0000-0000-0000-000000000001'),(select proposal from o8_result where proposal is not null),'acknowledged proposal JSON is unchanged');
set local role authenticated; select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claim.sub','fa100000-0000-0000-0000-000000000001',true);
select extensions.is((select charge_id from public.complete_treatment_case('fa300000-0000-0000-0000-000000000001','faa00000-0000-0000-0000-000000000001','fa900000-0000-0000-0000-000000000001',1,array['fab00000-0000-0000-0000-000000000001'::uuid],125000,'{"kind":"BRIDGE","units":[{"tooth_fdi":"24","ordinal":1,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"},{"tooth_fdi":"25","ordinal":2,"role":"PONTIC","support_kind":"NONE"},{"tooth_fdi":"26","ordinal":3,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"}]}'::jsonb,'o8-complete-once')),(select charge_id from o8_result where charge_id is not null),'duplicate completion returns original result');
select extensions.throws_ok($$select * from public.complete_treatment_case('fa300000-0000-0000-0000-000000000001','faa00000-0000-0000-0000-000000000002',null,1,array[]::uuid[],100,'{"kind":"BRIDGE","units":[{"tooth_fdi":"24","ordinal":1,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"},{"tooth_fdi":"25","ordinal":2,"role":"PONTIC","support_kind":"NONE"},{"tooth_fdi":"26","ordinal":3,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"}]}'::jsonb,'o8-complete-once')$$,'P0001','idempotency conflict','a completion key cannot replay a different procedure case');
reset role;
select extensions.is((select count(*)::integer from public.charges c join public.procedure_cases pc on pc.charge_id=c.id where pc.id='faa00000-0000-0000-0000-000000000001'),1,'duplicate does not post a second charge');
set local role authenticated; select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claim.sub','fa100000-0000-0000-0000-000000000001',true);
select extensions.throws_ok($$select * from public.complete_treatment_case('fa300000-0000-0000-0000-000000000001','faa00000-0000-0000-0000-000000000002',null,1,array[]::uuid[],100,'{"kind":"BRIDGE","units":[{"tooth_fdi":"24","ordinal":1,"role":"ABUTMENT","support_kind":"NATURAL_TOOTH"},{"tooth_fdi":"24","ordinal":2,"role":"PONTIC","support_kind":"NONE"}]}'::jsonb,'o8-invalid')$$,'22023','invalid bridge span','invalid downstream completion rolls back');
reset role;
select extensions.is((select count(*)::integer from public.charges c join public.procedure_cases pc on pc.charge_id=c.id where pc.id='faa00000-0000-0000-0000-000000000002'),0,'failed completion leaves no charge or clinical materialization');
select extensions.is((select current_state from public.treatment_plan_item_executions where item_id='fa900000-0000-0000-0000-000000000001'),'COMPLETED','linked plan execution is completed atomically');
with test_failures as (select finish from extensions.finish() where finish !~ '^1\.\.[0-9]+$') select case when count(*)=0 then 'P1_TEST_PASS' else string_agg(finish,E'\n') end as p1_test_result from test_failures;
rollback;
